"""Read the owned File #1 off-room movement coefficients at 0x829500."""

import hashlib
from pathlib import Path
import struct


ROOT = Path(__file__).resolve().parents[2]


def generated():
    image = (ROOT / "build-function-index/owned-overlays/o9.bin").read_bytes()
    assert hashlib.sha256(image).hexdigest() == "604126d6edca1b1333948d79d1d2c8d2f2e22f4a233efbdfb769c106dafe7343"
    offset = 0x829500 - 0x810000
    rows = [
        "// Owned File #1 movement coefficients. Generated by generate_ai_waypoint_speeds.py.",
        "constexpr std::array<std::array<std::uint32_t, 8>, 15> travel_speed_words{{",
    ]
    for row in range(15):
        values = struct.unpack_from("<8I", image, offset + 32 * row)
        rows.append("    {" + ", ".join(f"0x{value:08x}u" for value in values) + "},")
    return "\n".join(rows + ["}};", ""])


if __name__ == "__main__":
    (ROOT / "game/native/gameplay_ai/off_room_travel_speeds.inc").write_text(generated())
